import{_ as s,o as t,c as a,ae as i}from"./chunks/framework.B2ul6ABY.js";const g=JSON.parse('{"title":"Saivage v3 — Troubleshooting Guide","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting.md","filePath":"troubleshooting.md"}'),o={name:"troubleshooting.md"};function n(r,e,l,d,h,c){return t(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="saivage-v3-—-troubleshooting-guide" tabindex="-1">Saivage v3 — Troubleshooting Guide <a class="header-anchor" href="#saivage-v3-—-troubleshooting-guide" aria-label="Permalink to &quot;Saivage v3 — Troubleshooting Guide&quot;">​</a></h1><p>Common issues and their solutions.</p><h2 id="server-won-t-start" tabindex="-1">Server Won&#39;t Start <a class="header-anchor" href="#server-won-t-start" aria-label="Permalink to &quot;Server Won&#39;t Start&quot;">​</a></h2><h3 id="port-conflict" tabindex="-1">Port Conflict <a class="header-anchor" href="#port-conflict" aria-label="Permalink to &quot;Port Conflict&quot;">​</a></h3><p><strong>Symptom:</strong> <code>EADDRINUSE</code> error on startup.</p><p><strong>Solution:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Check what&#39;s using the port</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lsof</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> :8080</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Change the port in .saivage/saivage.json</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># {</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#   &quot;server&quot;: { &quot;port&quot;: 3000 }</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># }</span></span></code></pre></div><h3 id="missing-config-file" tabindex="-1">Missing Config File <a class="header-anchor" href="#missing-config-file" aria-label="Permalink to &quot;Missing Config File&quot;">​</a></h3><p><strong>Symptom:</strong> <code>Configuration not found at /path/.saivage/saivage.json</code></p><p><strong>Solution:</strong> Create <code>.saivage/saivage.json</code> with at minimum a <code>server</code> section:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;server&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;host&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0.0.0.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;port&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8080</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h3 id="invalid-config-json" tabindex="-1">Invalid Config JSON <a class="header-anchor" href="#invalid-config-json" aria-label="Permalink to &quot;Invalid Config JSON&quot;">​</a></h3><p><strong>Symptom:</strong> <code>Failed to parse saivage.json: ...</code></p><p><strong>Solution:</strong> Validate the JSON with <code>node -e &quot;JSON.parse(require(&#39;fs&#39;).readFileSync(&#39;.saivage/saivage.json&#39;,&#39;utf-8&#39;))&quot;</code> or <code>cat .saivage/saivage.json | python3 -m json.tool</code>.</p><h3 id="config-validation-failure" tabindex="-1">Config Validation Failure <a class="header-anchor" href="#config-validation-failure" aria-label="Permalink to &quot;Config Validation Failure&quot;">​</a></h3><p><strong>Symptom:</strong> <code>Configuration validation failed: ...</code></p><p><strong>Solution:</strong> The error message includes the path and issue (e.g., <code>server.port: Expected number, received string</code>). Fix the field in <code>.saivage/saivage.json</code>.</p><h3 id="stale-runtime-lock" tabindex="-1">Stale Runtime Lock <a class="header-anchor" href="#stale-runtime-lock" aria-label="Permalink to &quot;Stale Runtime Lock&quot;">​</a></h3><p><strong>Symptom:</strong> <code>Runtime lock is held by PID 12345 (started ...). Cannot acquire lock.</code></p><p><strong>Solution:</strong> If PID 12345 is no longer running (verify with <code>ps aux | grep 12345</code>), remove the lock:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .saivage-work/tmp/runtime/runtime.lock</span></span></code></pre></div><p>Then restart. Locks older than 14 days are automatically treated as stale.</p><h3 id="missing-api-token" tabindex="-1">Missing API Token <a class="header-anchor" href="#missing-api-token" aria-label="Permalink to &quot;Missing API Token&quot;">​</a></h3><p><strong>Symptom:</strong> Server starts but all <code>/api/*</code> requests return <code>401 Unauthorized</code>.</p><p><strong>Solution:</strong> Either:</p><ol><li>Set <code>SAIVAGE_API_TOKEN</code> when starting the server, or</li><li>If you intentionally want open access, leave <code>SAIVAGE_API_TOKEN</code> unset (the server runs with no auth).</li></ol><hr><h2 id="api-returns-401" tabindex="-1">API Returns 401 <a class="header-anchor" href="#api-returns-401" aria-label="Permalink to &quot;API Returns 401&quot;">​</a></h2><p><strong>Symptom:</strong> <code>{&quot;error&quot;:&quot;Unauthorized&quot;,&quot;statusCode&quot;:401}</code></p><p><strong>Solution:</strong></p><ol><li>Verify <code>SAIVAGE_API_TOKEN</code> is set in the server&#39;s environment.</li><li>Verify you&#39;re sending the correct token in the <code>Authorization: Bearer &lt;token&gt;</code> header.</li><li>If using query parameter, ensure <code>?token=&lt;value&gt;</code> matches exactly.</li><li>The <code>/health</code> endpoint does not require auth — test it first to confirm the server is running.</li></ol><hr><h2 id="health-endpoint-shows-unexpected-runtime-status" tabindex="-1">Health Endpoint Shows Unexpected Runtime Status <a class="header-anchor" href="#health-endpoint-shows-unexpected-runtime-status" aria-label="Permalink to &quot;Health Endpoint Shows Unexpected Runtime Status&quot;">​</a></h2><p><strong>Symptom:</strong> <code>/health</code> returns <code>runtime: &quot;idle&quot;</code> but you expect <code>running</code>.</p><p><strong>Solution:</strong> The health endpoint reads from <code>.saivage/runtime/state.json</code>. Check the file directly:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .saivage/runtime/state.json</span></span></code></pre></div><p>If the file is stale or doesn&#39;t exist, the <code>/health</code> endpoint returns <code>&quot;unknown&quot;</code>. This is expected behavior — the health endpoint reports truthfully what&#39;s on disk, not a guess.</p><hr><h2 id="card-operations-fail" tabindex="-1">Card Operations Fail <a class="header-anchor" href="#card-operations-fail" aria-label="Permalink to &quot;Card Operations Fail&quot;">​</a></h2><p><strong>Symptom:</strong> <code>POST /api/cards</code> returns <code>400</code> with a validation message.</p><p><strong>Solution:</strong> Check the card fields:</p><ul><li><code>type</code> must be a valid card type (<code>architecture</code>, <code>code</code>, <code>test</code>, <code>doc</code>, <code>data</code>, <code>research</code>, <code>ops</code>, <code>plan</code>, <code>project</code>).</li><li><code>parent</code> must be an existing card ID if provided.</li><li>Plan cards (<code>type: &quot;plan&quot;</code>) cannot be created without a parent.</li></ul><h3 id="card-not-found" tabindex="-1">Card Not Found <a class="header-anchor" href="#card-not-found" aria-label="Permalink to &quot;Card Not Found&quot;">​</a></h3><p><strong>Symptom:</strong> <code>{&quot;error&quot;:&quot;Card not found&quot;,&quot;cardId&quot;:&quot;...&quot;}</code></p><p><strong>Solution:</strong> List all cards to verify the ID:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer token&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8080/api/cards</span></span></code></pre></div><h3 id="card-store-integrity" tabindex="-1">Card Store Integrity <a class="header-anchor" href="#card-store-integrity" aria-label="Permalink to &quot;Card Store Integrity&quot;">​</a></h3><p>If card operations fail unexpectedly, check the card store files:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .saivage/cards/by-id/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .saivage/cards/index.json</span></span></code></pre></div><p>Verify that every card referenced in the index has a corresponding file under <code>by-id/</code>.</p><hr><h2 id="agent-produces-no-output" tabindex="-1">Agent Produces No Output <a class="header-anchor" href="#agent-produces-no-output" aria-label="Permalink to &quot;Agent Produces No Output&quot;">​</a></h2><p><strong>Symptom:</strong> Cards stuck in <code>running</code> or <code>active</code> status, no agent output.</p><p><strong>Solutions:</strong></p><ol><li><strong>Check model configuration</strong>: Verify the model names in <code>models</code> match what&#39;s in <code>providers</code>. Model strings should be provider-specific.</li><li><strong>Check provider API keys</strong>: If using <code>\${ENV_VAR}</code> references, verify the environment variable is set in the server&#39;s environment.</li><li><strong>Check network</strong>: The server needs outbound HTTPS access to LLM provider APIs.</li><li><strong>Check logs</strong>: Look for API error responses in the server&#39;s stdout logs.</li><li><strong>Check debug state</strong>: <code>GET /api/debug/state</code> shows current card statuses and execution state.</li></ol><hr><h2 id="mcp-servers-fail-to-start" tabindex="-1">MCP Servers Fail to Start <a class="header-anchor" href="#mcp-servers-fail-to-start" aria-label="Permalink to &quot;MCP Servers Fail to Start&quot;">​</a></h2><p><strong>Symptom:</strong> <code>MCP manager initialization failed (continuing without MCP): ...</code></p><p><strong>Solutions:</strong></p><ol><li><strong>Check command path</strong>: The <code>command</code> field in <code>mcpServers.&lt;name&gt;</code> must be an executable on the server&#39;s PATH or an absolute path.</li><li><strong>Check transport type</strong>: Must be <code>&quot;stdio&quot;</code> or <code>&quot;sse&quot;</code>.</li><li><strong>Check environment</strong>: Use the <code>env</code> field to pass needed environment variables.</li><li><strong>Check MCP status</strong>: <code>GET /api/mcp/status</code> shows which servers are running and their statuses.</li><li><strong>Disable problematic servers</strong>: Set <code>&quot;disabled&quot;: true</code> on a server to prevent startup.</li></ol><hr><h2 id="telegram-bot-doesn-t-respond" tabindex="-1">Telegram Bot Doesn&#39;t Respond <a class="header-anchor" href="#telegram-bot-doesn-t-respond" aria-label="Permalink to &quot;Telegram Bot Doesn&#39;t Respond&quot;">​</a></h2><p><strong>Symptom:</strong> Bot starts but doesn&#39;t respond to messages.</p><p><strong>Solutions:</strong></p><ol><li><strong>Check bot token</strong>: Verify the <code>botToken</code> is correct and not expired.</li><li><strong>Check allowed user IDs</strong>: If <code>allowedUserIds</code> is set, only those users can interact with the bot. Add your user ID to the list.</li><li><strong>Check network</strong>: The bot uses long polling — outbound HTTPS to <code>api.telegram.org</code> is required.</li><li><strong>Check logs</strong>: Look for Telegram API errors in the server stdout.</li></ol><hr><h2 id="websocket-disconnects" tabindex="-1">WebSocket Disconnects <a class="header-anchor" href="#websocket-disconnects" aria-label="Permalink to &quot;WebSocket Disconnects&quot;">​</a></h2><p><strong>Symptom:</strong> WebSocket connection drops frequently.</p><p><strong>Solutions:</strong></p><ol><li><strong>Check auth</strong>: WebSocket connections require authentication (same token as API). Include <code>?token=&lt;value&gt;</code> in the WebSocket URL.</li><li><strong>Check network stability</strong>: WebSocket connections expect a stable connection. Proxy servers with short idle timeouts may drop them.</li><li><strong>Check server logs</strong>: Look for WebSocket-related errors.</li></ol><hr><h2 id="large-files-can-t-be-read-via-api" tabindex="-1">Large Files Can&#39;t Be Read via API <a class="header-anchor" href="#large-files-can-t-be-read-via-api" aria-label="Permalink to &quot;Large Files Can&#39;t Be Read via API&quot;">​</a></h2><p><strong>Symptom:</strong> <code>GET /api/files/content?path=largefile.log</code> returns <code>413</code>.</p><p><strong>Solution:</strong> The file content API has a 1 MB limit (<code>MAX_FILE_SIZE_BYTES = 1_048_576</code>). For larger files, read them directly from the filesystem:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .saivage-work/tmp/processes/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">procI</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/output.txt</span></span></code></pre></div><hr><h2 id="config-changes-don-t-take-effect" tabindex="-1">Config Changes Don&#39;t Take Effect <a class="header-anchor" href="#config-changes-don-t-take-effect" aria-label="Permalink to &quot;Config Changes Don&#39;t Take Effect&quot;">​</a></h2><p><strong>Symptom:</strong> Updated <code>.saivage/saivage.json</code> but changes aren&#39;t reflected.</p><p><strong>Solution:</strong> Most configuration is loaded at server startup and cached in memory. Restart the server for changes to take effect:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Stop (Ctrl+C), then start again</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SAIVAGE_API_TOKEN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your-token</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dist/src/server/server.js</span></span></code></pre></div><p>Exception: The <code>/api/runtime/pause</code> and <code>/api/runtime/resume</code> endpoints change runtime state at runtime — these don&#39;t require restart.</p><hr><h2 id="runtime-stuck-after-crash" tabindex="-1">Runtime Stuck After Crash <a class="header-anchor" href="#runtime-stuck-after-crash" aria-label="Permalink to &quot;Runtime Stuck After Crash&quot;">​</a></h2><p><strong>Symptom:</strong> Server won&#39;t start after a crash, lock-related error.</p><p><strong>Solution:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. Verify the process is truly dead</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ps</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> aux</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> saivage</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. If dead, remove the stale lock</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .saivage-work/tmp/runtime/runtime.lock</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3. Restart (crash recovery will run automatically)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SAIVAGE_API_TOKEN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your-token</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dist/src/server/server.js</span></span></code></pre></div><hr><h2 id="where-to-find-logs" tabindex="-1">Where to Find Logs <a class="header-anchor" href="#where-to-find-logs" aria-label="Permalink to &quot;Where to Find Logs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Log Type</th><th>Location</th></tr></thead><tbody><tr><td>Server logs</td><td>stdout (pino JSON or pretty-printed)</td></tr><tr><td>Process output</td><td><code>.saivage-work/tmp/processes/&lt;procId&gt;/</code></td></tr><tr><td>Error log</td><td><code>.saivage/runtime/errors.jsonl</code></td></tr><tr><td>Event timeline</td><td><code>.saivage/runtime/events.jsonl</code></td></tr><tr><td>Content reviews</td><td><code>.saivage/supervision/reviews.jsonl</code></td></tr></tbody></table><h3 id="increasing-log-verbosity" tabindex="-1">Increasing Log Verbosity <a class="header-anchor" href="#increasing-log-verbosity" aria-label="Permalink to &quot;Increasing Log Verbosity&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">LOG_LEVEL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">debug</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> SAIVAGE_API_TOKEN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">test</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dist/src/server/server.js</span></span></code></pre></div><p>For trace-level (very verbose):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">LOG_LEVEL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">trace</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> NODE_ENV</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">development</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> SAIVAGE_API_TOKEN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">test</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dist/src/server/server.js</span></span></code></pre></div><hr><h2 id="file-access-security-issues" tabindex="-1">File Access Security Issues <a class="header-anchor" href="#file-access-security-issues" aria-label="Permalink to &quot;File Access Security Issues&quot;">​</a></h2><h3 id="auth-profiles-json-blocked" tabindex="-1">auth-profiles.json Blocked <a class="header-anchor" href="#auth-profiles-json-blocked" aria-label="Permalink to &quot;auth-profiles.json Blocked&quot;">​</a></h3><p><strong>Symptom:</strong> <code>GET /api/files/content?path=.saivage/auth-profiles.json</code> returns <code>403</code>.</p><p><strong>Solution:</strong> This is by design. <code>auth-profiles.json</code> contains OAuth credentials and is blocked from all API read access. Access it directly on the filesystem if needed (with appropriate filesystem permissions).</p><h3 id="saivage-json-secrets-redacted" tabindex="-1">saivage.json Secrets Redacted <a class="header-anchor" href="#saivage-json-secrets-redacted" aria-label="Permalink to &quot;saivage.json Secrets Redacted&quot;">​</a></h3><p><strong>Symptom:</strong> <code>GET /api/config</code> shows <code>&quot;[REDACTED]&quot;</code> for API key values.</p><p><strong>Solution:</strong> This is by design. The config API redacts literal secret values. Use environment variable references (<code>\${ENV_VAR}</code>) for secrets so they are never in the config file as plaintext. The API serves redacted config to prevent secret leakage.</p>`,101)])])}const u=s(o,[["render",n]]);export{g as __pageData,u as default};
